#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int count;
    cin >> count;
    if (count >= 100) {
        cout << 0 << "\n";
    } else {
        vector<int> A(count + 1), B(count + 1), C(count + 1), D(count + 1), E(count + 1);
        for (int i = 1; i <= count; i++) {
            cin >> A[i] >> B[i] >> C[i] >> D[i] >> E[i];
        }
        unordered_set<int> badIndices;
        for (int i = 1; i <= count; i++) {
            for (int j = 1; j <= count; j++) {
                if (j == i) continue;
                for (int k = 1; k <= count; k++) {
                    if (k == i || k == j) continue;
                    long long deltaA = A[j] - A[i], deltaB = B[j] - B[i], deltaC = C[j] - C[i], deltaD = D[j] - D[i], deltaE = E[j] - E[i];
                    long long deltaA2 = A[k] - A[i], deltaB2 = B[k] - B[i], deltaC2 = C[k] - C[i], deltaD2 = D[k] - D[i], deltaE2 = E[k] - E[i];

                    double dotProd = deltaA * deltaA2 + deltaB * deltaB2 + deltaC * deltaC2 + deltaD * deltaD2 + deltaE * deltaE2;
                    long long mag1 = deltaA * deltaA + deltaB * deltaB + deltaC * deltaC + deltaD * deltaD + deltaE * deltaE;
                    long long mag2 = deltaA2 * deltaA2 + deltaB2 * deltaB2 + deltaC2 * deltaC2 + deltaD2 * deltaD2 + deltaE2 * deltaE2;

                    double cosine = 0.0;
                    if (mag1 != 0 && mag2 != 0) {
                        cosine = dotProd / (sqrt((double)mag1) * sqrt((double)mag2));
                        // Clamp cosine to [-1,1] to avoid numerical issues
                        if (cosine > 1.0) cosine = 1.0;
                        if (cosine < -1.0) cosine = -1.0;
                    }

                    double angle_deg = acos(cosine) * 180.0 / M_PI;
                    if (angle_deg + 1e-9 < 90.0) {
                        badIndices.insert(i);
                        break; // No need to check further for this i
                    }
                }
                if (badIndices.count(i)) break; // Already marked as bad
            }
        }
        cout << count - (int)badIndices.size() << "\n";
        for (int i = 1; i <= count; i++) {
            if (badIndices.count(i) == 0) {
                cout << i << "\n";
            }
        }
    }
    return 0;
}

